
    #[test]
    fn child_complete_group_source_candidate_fingerprint_preserves_original_spans_and_refused_output(){
        mod fingerprint{include!("./🧩️child-operations/🔏️fingerprint/🦀️.rs");}
        use semio_framework_os_kernel::{os_pack::{codec::ByteSpan,PackRefusal},os_spr::operation_bytes::OperationSourceCollection};
        use semio_framework_value::{NativeEncodeControl,list::PagedList};
        use std::sync::atomic::{AtomicUsize,Ordering};
        struct Order<'a>{original:&'a PagedList<OwnedOperationBytes,2>,indices:&'a[usize],missing:bool}
        impl OperationSourceCollection for Order<'_>{fn len(&self)->usize{self.indices.len()}fn source_at(&self,index:usize)->Option<ByteSpan<'_>>{if self.missing&&index==1{return None}self.original.source_at(*self.indices.get(index)?)}}
        struct Observed<'a>{original:&'a mut OwnedOperationBytes,accepted:&'a AtomicUsize}
        impl OperationByteOutput for Observed<'_>{fn write_bytes(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackRefusal>{for byte in bytes{self.original.write_bytes(&[*byte],control)?;self.accepted.fetch_add(1,Ordering::Relaxed);}Ok(())}}
        let f:serde_json::Value=serde_json::from_str(include_str!("@OPERATION_FINGERPRINT_SOURCE_FIXTURE@")).unwrap();assert_eq!(f["sourceBytes"],8194);assert_eq!(f["maximumAllocationBytes"],65536);assert_eq!(f["maximumItems"],1);assert_eq!(f["maximumBytes"],4096);assert_eq!(f["lengthPrefixBytes"],8);
        let mut allow=|_|true;let mut input_control=NativeEncodeControl::new(65536,&mut allow);let mut original=PagedList::<OwnedOperationBytes,2>::empty();for index in 0..2{let mut source=OwnedOperationBytes::try_new(if index==0{8194}else{4},65536).unwrap();if index==0{source.write_bytes(b"17",&mut input_control).unwrap();for _ in 0..8192{source.write_bytes(b" ",&mut input_control).unwrap();}}else{source.write_bytes(&[0,127,128,255],&mut input_control).unwrap();}while !original.has_reserved_slot(){let required=original.next_allocation_bytes().unwrap();assert!(required<=4096);input_control.charge(required).unwrap();let step=original.reserve_one(4096).unwrap();assert!(step.progressed);assert_eq!(step.allocated_bytes,required);}assert!(original.push_reserved(source).is_ok());}
        let pointers=[original[0].byte_ref(0).map(|byte|byte as *const u8).unwrap(),original[1].byte_ref(0).map(|byte|byte as *const u8).unwrap()];assert_ne!(pointers[0],pointers[1]);let input_allocated=original.allocated_bytes()+original.iter().map(OwnedOperationBytes::allocated_bytes).sum::<usize>();assert_eq!(input_allocated,input_control.owned_bytes());
        for order in f["sourceOrders"].as_array().unwrap(){let order=order.as_array().unwrap();let indices:[usize;2]=std::array::from_fn(|index|order.get(index).and_then(serde_json::Value::as_u64).unwrap_or(0)as usize);let source=Order{original:&original,indices:&indices[..order.len()],missing:false};let extent=source.indices.iter().map(|index|8+if *index==0{8194}else{4}).sum::<usize>();if extent==0{let mut output=semio_framework_os_kernel::os_spr::operation_bytes::OperationByteComparison::new(ByteSpan::from_slice(&[]));let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);fingerprint::write_operation_fingerprint_into(&source,&mut output,&mut control).unwrap();output.finish().unwrap();assert_eq!(control.owned_bytes(),0);for(index,pointer)in pointers.iter().enumerate(){assert_eq!(original[index].byte_ref(0).map(|byte|byte as *const u8),Some(*pointer));}continue;}let mut output=OwnedOperationBytes::try_new(extent,65536).unwrap();let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);fingerprint::write_operation_fingerprint_into(&source,&mut output,&mut control).unwrap();assert_eq!(output.len(),extent);let mut at=0;for index in source.indices{let length=if *index==0{8194usize}else{4};for byte in(length as u64).to_le_bytes(){assert_eq!(output.byte_at(at),Some(byte));at+=1;}for position in 0..length{let expected=if *index==0{if position==0{b'1'}else if position==1{b'7'}else{b' '}}else{[0,127,128,255][position]};assert_eq!(output.byte_at(at),Some(expected));at+=1;}}assert_eq!(at,extent);let allocated=output.allocated_bytes();assert_eq!(allocated,control.owned_bytes());drain(&mut output);assert!(output.terminal_is_empty());for(index,pointer)in pointers.iter().enumerate(){assert_eq!(original[index].byte_ref(0).map(|byte|byte as *const u8),Some(*pointer));}assert_eq!(input_allocated,original.allocated_bytes()+original.iter().map(OwnedOperationBytes::allocated_bytes).sum::<usize>());}
        for mode in["missing-source","output-one-short","initial4096","interior-cancel"]{let accepted=AtomicUsize::new(0);let mut callback=|_:semio_framework_value::native_encoding::NativeEncodeProgress|mode!="interior-cancel"||accepted.load(Ordering::Relaxed)<256;let mut control=NativeEncodeControl::new(if mode=="initial4096"{4096}else{65536},&mut callback);let mut output=OwnedOperationBytes::try_new(if mode=="output-one-short"{8201}else{8214},65536).unwrap();let source=Order{original:&original,indices:&[0,1],missing:mode=="missing-source"};assert!(fingerprint::write_operation_fingerprint_into(&source,&mut Observed{original:&mut output,accepted:&accepted},&mut control).is_err());match mode{"missing-source"=>assert_eq!(output.len(),8202),"output-one-short"=>assert_eq!(output.len(),8201),"initial4096"=>assert_eq!(output.len(),0),"interior-cancel"=>{assert_eq!(output.len(),256);assert_eq!(accepted.load(Ordering::Relaxed),256);},_=>unreachable!()}assert_eq!(output.allocated_bytes(),control.owned_bytes());drain(&mut output);assert!(output.terminal_is_empty());for(index,pointer)in pointers.iter().enumerate(){assert_eq!(original[index].byte_ref(0).map(|byte|byte as *const u8),Some(*pointer));}assert_eq!(input_allocated,original.allocated_bytes()+original.iter().map(OwnedOperationBytes::allocated_bytes).sum::<usize>());}
        while let Some(source)=original.get_mut(original.len().saturating_sub(1)){drain(source);original.pop();}while !original.terminal_is_empty(){let step=original.release_empty_page(4096).unwrap();assert!(step.progressed);assert!(step.released_allocation_bytes<=4096);}assert_eq!(input_control.owned_bytes(),input_allocated);eprintln!("[DEBUG] original8194 and binary4 operation sources keep exact pointers and allocations through all0/8202/8214/8214 fingerprints, missing ordinal,one-short,actual initial4096 and interior256 refusal; only actual output pages retire, then original payload/outer pages explicitly close1/4096; no digest, IDs or Store caller credit");
    }
